/**
 * The real task on /ai (#593) is drawn from pinned GitHub events
 * (`src/data/task-timeline.json`, regenerated by
 * `scripts/fetch-task-timeline.sh <pr>`). The expected phases below were
 * read by hand from those events; regenerating the file means re-reading them.
 */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { duration, phases } from '../src/lib/task-timeline.mjs';

const siteRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const task = JSON.parse(readFileSync(join(siteRoot, 'src/data/task-timeline.json'), 'utf8'));

test('the task is a merged PR of this repository that closes an issue', () => {
  assert.equal(task.repo, 'mlorentedev/web');
  assert.ok(Number.isInteger(task.pr) && Number.isInteger(task.issue));
  const merged = task.events.find((e) => e.kind === 'merged');
  assert.equal(merged?.url, `https://github.com/mlorentedev/web/pull/${task.pr}`);
  assert.match(task.events.find((e) => e.kind === 'plan').url, new RegExp(`/issues/${task.issue}#issuecomment-\\d+$`));
});

test('the events are in time order and each one links where it happened', () => {
  const times = task.events.map((e) => Date.parse(e.at));
  assert.ok(times.every(Number.isFinite), 'an event has no valid time');
  assert.deepEqual(times, [...times].sort((a, b) => a - b));
  for (const e of task.events) assert.match(e.url, /^https:\/\/github\.com\/mlorentedev\/web\//);
});

test('the phases match the ones read by hand from the events, and add up to plan → merge', () => {
  const got = phases(task.events);
  assert.deepEqual(
    got.map((p) => [p.phase, p.minutes]),
    [
      ['work', 101],
      ['review', 22],
      ['fix', 2],
      ['land', 15],
    ],
  );
  const total = (Date.parse(task.events.at(-1).at) - Date.parse(task.events[0].at)) / 60000;
  assert.ok(Math.abs(got.reduce((n, p) => n + p.minutes, 0) - total) < 2);
});

test('durations read as hours and minutes', () => {
  assert.equal(duration(101), '1 h 41 min');
  assert.equal(duration(22), '22 min');
});

test('a fix phase ends at the last commit or triage after the review, before the merge', () => {
  const ev = (kind, at) => ({ kind, at: `2026-01-01T${at}:00Z`, url: 'u' });
  const p = phases([ev('plan', '00:00'), ev('opened', '01:00'), ev('review', '01:10'), ev('commit', '01:20'), ev('triage', '01:25'), ev('merged', '02:00')]);
  assert.deepEqual(p.map((x) => x.minutes), [60, 10, 15, 35]);
});
